use vstd::prelude::*;

verus! {
    /// Given an input vector `s` of i8’s, return a new vector `res` of the same length
    /// such that
    ///   let L = s.len(),
    ///       P = L - (L % 3);
    /// then for each i < P:
    ///     if i % 3 == 0  =>  res[i] == s[i+2]
    ///     otherwise      =>  res[i] == s[i-1]
    /// and for each P <= i < L:
    ///     res[i] == s[i].
    fn decode_cyclic(s: &Vec<i8>) -> (res: Vec<i8>)
        ensures
            res.len() == s.len() &&
            // for all positions i < L, the element is rewritten correctly
            forall |i: usize| i < s.len() ==>
                let L = s.len();
                let rem = L % 3;
                let P = L - rem;
                if i < P {
                    if i % 3 == 0 {
                        res[i] == s[i + 2]
                    } else {
                        res[i] == s[i - 1]
                    }
                } else {
                    res[i] == s[i]
                }
    {
        let L = s.len();
        let rem = L % 3;
        let P = L - rem;

        // We'll build res element by element.
        let mut res = Vec::with_capacity(L);
        let mut i: usize = 0;

        // First loop: rewrite the first P = (L - L%3) elements in cyclic blocks of 3
        while i < P
            invariant: 0 <= i && i <= P
            invariant: res.len() == i
            invariant: forall |j: usize| j < i ==>
                // every element j < i already satisfies the desired property
                if j < P {
                    if j % 3 == 0 {
                        res[j] == s[j + 2]
                    } else {
                        res[j] == s[j - 1]
                    }
                } else {
                    // this branch cannot actually occur in this first loop,
                    // but we include it for uniformity
                    res[j] == s[j]
                }
            decreases P - i
        {
            // push the appropriately‐shifted element
            if i % 3 == 0 {
                res.push(s[i + 2]);
            } else {
                res.push(s[i - 1]);
            }
            i += 1;
        }
        // At this point i == P
        assert(i == P);

        // Second loop: copy the remaining rem = L%3 elements straight through
        while i < L
            invariant: P <= i && i <= L
            invariant: res.len() == i
            invariant: forall |j: usize| j < i ==>
                // j < i already satisfies the overall spec:
                //   if j < P then cyclic‐rewrite else identity
                if j < P {
                    if j % 3 == 0 {
                        res[j] == s[j + 2]
                    } else {
                        res[j] == s[j - 1]
                    }
                } else {
                    res[j] == s[j]
                }
            decreases L - i
        {
            res.push(s[i]);
            i += 1;
        }

        // Now we've produced exactly L elements
        assert(res.len() == L);
        res
    }
}